def unique_slug(title, used, max_length=40):
    base = base_slug(title)[:max_length]
    result = base
    number = 2
    while result in used:
        # Truncate base to leave space for suffix
        if len(base) + len(f'-{number}') > max_length:
            base = base[:max_length - len(f'-{number}')]
        result = f'{base}-{number}'
        number += 1
    return result
"}

